  "tagline": "Exploratory: is the latent space worth looking at?",
  "components": [
   {
    "name": "First attempts",
    "subtitle": "What gets built and run first",
    "state": "next",
    "summary": "Small, cheap probes chosen so that a negative answer arrives quickly. Each one reuses models that already exist or come out of the baseline re-run.",
    "items": [
     {
      "label": "Probe set",
      "detail": "Carve out held-out events before cross-validation so every model is compared on data none of them trained on"
     },
     {
      "label": "Model space",
      "detail": "One point per trained model, distances from per-event predicted probabilities, embedded the way the training-manifold work does [@mao2024][@klabunde2025]"
     },
     {
      "label": "Event space",
      "detail": "Hidden-layer activations of a single model, compared across seeds and objectives with CKA and its known failure modes guarded [@kornblith2019][@davari2023]"
     },
     {
      "label": "Positive control",
      "detail": "A known change in training regime along the decorrelation sweep should show up as a kink in the model-space trajectory; if it does not, the map is not seeing real structure"
     },
     {
      "label": "Dead-unit census",
      "detail": "Count hidden units that never activate, which also feeds the connection sizing in TRUSS [@khot2023]"
     }
    ]
   },
   {
    "name": "The heat-map idea",
    "subtitle": "Where this could become useful",
    "state": "next",
    "summary": "Color latent space by background closure, signal density, or per-event contribution to the closure error, so regions where the ABCD estimate breaks down become visible. This is the version of the idea that could earn its keep; it is not yet known whether such regions exist.",
    "items": [
     {
      "label": "Intrinsic dimension",
      "detail": "Measure how many directions the representation actually uses before mapping it, with shuffled and untrained controls [@ansuini2019]"
     },
     {
      "label": "Stability",
      "detail": "Display only structures that persist across seeds and projection choices; mode connectivity tests whether two solutions are really distinct [@garipov2018]"
     }
    ]
   },
   {
    "name": "Kill test",
    "subtitle": "Pre-registered exit",
    "state": "next",
    "summary": "Before anything is built into a tool, test whether map-derived quantities predict closure on held-out events better than the training hyperparameters alone. If they do not, the project stops with that result written down."
   }
  ],
